/// The lexer (lexical analyzer) preprocesses raw SQL strings into a sequence of
/// lexical tokens (e.g. keyword, number, string, etc), which are passed on to
/// the SQL parser. In doing so, it strips away basic syntactic noise such as
/// whitespace, case, and quotes, and performs initial symbol validation.
pub struct Lexer<'a> {
    chars: Peekable<Chars<'a>>,
}

/// The lexer is used as a token iterator.
impl Iterator for Lexer<'_> {
    type Item = Result<Token>;

    fn next(&mut self) -> Option<Result<Token>> {
        self.skip_whitespace();
        self.scan().transpose()
    }
}

impl<'a> Lexer<'a> {
    /// Creates a new lexer for the given string.
    pub fn new(input: &'a str) -> Lexer<'a> {
        Self {
            chars: input.chars().peekable(),
        }
    }

    /// Returns the next character if it satisfies the predicate.
    fn next_if(&mut self, predicate: impl Fn(char) -> bool) -> Option<char> {
        let c = *self.chars.peek()?;
        if predicate(c) {
            self.chars.next();
            Some(c)
        } else {
            None
        }
    }

    /// Applies a closure to the next character, returning its result and
    /// consuming the next character if it's Some.
    fn next_if_map<T>(&mut self, map: impl Fn(char) -> Option<T>) -> Option<T> {
        let c = *self.chars.peek()?;
        map(c).map(|_| self.chars.next())
    }

    /// Returns true if the next character is the given character, consuming it.
    fn next_is(&mut self, c: char) -> bool {
        self.next_if(|x| x == c).is_some()
    }

    /// Scans the next token, if any.
    fn scan(&mut self) -> Result<Option<Token>> {
        // Scan symbols first (multi-char operators).
        if let Some(token) = self.scan_symbol() {
            return Ok(Some(token));
        }

        // Scan numbers.
        if let Some(token) = self.scan_number() {
            return Ok(Some(token));
        }

        // Scan quoted identifiers.
        if let Some(token) = self.scan_ident_quoted()? {
            return Ok(Some(token));
        }

        // Scan quoted strings.
        if let Some(token) = self.scan_string()? {
            return Ok(Some(token));
        }

        // Scan identifiers or keywords.
        if let Some(token) = self.scan_ident_or_keyword() {
            return Ok(Some(token));
        }

        Ok(None)
    }

    /// Scans the next identifier or keyword, if any. It's converted to
    /// lowercase, by SQL convention.
    fn scan_ident_or_keyword(&mut self) -> Option<Token> {
        let mut ident = String::new();
        while let Some(c) = self.next_if_map(|c| c.is_alphanumeric() || c == '_') {
            ident.push(c);
        }
        if ident.is_empty() {
            return None;
        }

        // Try to parse as a keyword.
        match Keyword::try_from(ident.as_str()) {
            Ok(keyword) => Some(Token::Keyword(keyword)),
            Err(_) => Some(Token::Ident(ident)),
        }
    }

    /// Scans the next quoted identifier, if any. Case is preserved.
    fn scan_ident_quoted(&mut self) -> Result<Option<Token>> {
        if !self.next_is('"') {
            return Ok(None);
        }

        let mut ident = String::new();
        loop {
            match self.chars.next() {
                Some('"') => {
                    // Check for escaped quote.
                    if self.next_is('"') {
                        ident.push('"');
                    } else {
                        break;
                    }
                }
                Some(c) => ident.push(c),
                None => return errinput!("unterminated quoted identifier"),
            }
        }

        Ok(Some(Token::Ident(ident)))
    }

    /// Scans the next number, if any.
    fn scan_number(&mut self) -> Option<Token> {
        let mut num = String::new();

        // Optional sign.
        if self.next_if(|c| c == '+' || c == '-') {
            num.push('-');
        }

        // Integer part.
        let mut has_digit = false;
        while let Some(c) = self.next_if(|c| c.is_ascii_digit()) {
            num.push(c);
            has_digit = true;
        }

        // Decimal point and fractional part.
        if self.next_is('.') {
            num.push('.');
            while let Some(c) = self.next_if(|c| c.is_ascii_digit()) {
                num.push(c);
                has_digit = true;
            }
        }

        // Exponent.
        if let Some('e' | 'E') = self.chars.peek() {
            num.push('e');
            self.chars.next();
            if self.next_if(|c| c == '+' || c == '-') {
                num.push('-');
            }
            while let Some(c) = self.next_if(|c| c.is_ascii_digit()) {
                num.push(c);
                has_digit = true;
            }
        }

        if has_digit {
            Some(Token::Number(num))
        } else {
            None
        }
    }

    /// Scans the next quoted string literal, if any.
    fn scan_string(&mut self) -> Result<Option<Token>> {
        if !self.next_is('\'') {
            return Ok(None);
        }

        let mut s = String::new();
        loop {
            match self.chars.next() {
                Some('\'') => {
                    // Check for escaped quote.
                    if self.next_is('\'') {
                        s.push('\'');
                    } else {
                        break;
                    }
                }
                Some('\\') => {
                    // Escape sequences.
                    match self.chars.next() {
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('\\') => s.push('\\'),
                        Some('\'') => s.push('\''),
                        Some(c) => {
                            s.push('\\');
                            s.push(c);
                        }
                        None => return errinput!("unterminated escape sequence"),
                    }
                }
                Some(c) => s.push(c),
                None => return errinput!("unterminated string literal"),
            }
        }

        Ok(Some(Token::String(s)))
    }

    /// Scans the next symbol token, if any.
    fn scan_symbol(&mut self) -> Option<Token> {
        let c = *self.chars.peek()?;
        match c {
            '.' => {
                self.chars.next();
                Some(Token::Period)
            }
            '=' => {
                self.chars.next();
                Some(Token::Equal)
            }
            '!' => {
                self.chars.next();
                if self.next_is('=') {
                    Some(Token::NotEqual)
                } else {
                    Some(Token::Exclamation)
                }
            }
            '<' => {
                self.chars.next();
                match self.chars.peek() {
                    Some('=') => {
                        self.chars.next();
                        Some(Token::LessThanOrEqual)
                    }
                    Some('>') => {
                        self.chars.next();
                        Some(Token::LessOrGreaterThan)
                    }
                    _ => Some(Token::LessThan),
                }
            }
            '>' => {
                self.chars.next();
                if self.next_is('=') {
                    Some(Token::GreaterThanOrEqual)
                } else {
                    Some(Token::GreaterThan)
                }
            }
            '+' => {
                self.chars.next();
                Some(Token::Plus)
            }
            '-' => {
                self.chars.next();
                Some(Token::Minus)
            }
            '*' => {
                self.chars.next();
                Some(Token::Asterisk)
            }
            '/' => {
                self.chars.next();
                Some(Token::Slash)
            }
            '^' => {
                self.chars.next();
                Some(Token::Caret)
            }
            '%' => {
                self.chars.next();
                Some(Token::Percent)
            }
            '?' => {
                self.chars.next();
                Some(Token::Question)
            }
            ',' => {
                self.chars.next();
                Some(Token::Comma)
            }
            ';' => {
                self.chars.next();
                Some(Token::Semicolon)
            }
            '(' => {
                self.chars.next();
                Some(Token::OpenParen)
            }
            ')' => {
                self.chars.next();
                Some(Token::CloseParen)
            }
            _ => None,
        }
    }

    /// Skips any whitespace.
    fn skip_whitespace(&mut self) {
        while self.next_if(|c| c.is_whitespace()) {}
    }
}

/// Returns true if the entire given string is a single valid identifier.
pub fn is_ident(ident: &str) -> bool {
    if ident.is_empty() {
        return false;
    }
    let mut chars = ident.chars();
    let first = chars.next().unwrap();
    if !first.is_ascii_alphabetic() && first != '_' {
        return false;
    }
    chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
}
